from __future__ import annotations

import html
import json


SHELL_CSS = r"""
:root{--bg:#090c0d;--panel:#111617;--panel2:#171d1e;--line:#393323;--line2:#303635;--gold:#d5a54a;--gold2:#f0c66e;--text:#eeeae0;--muted:#a6aaa6;--good:#70d39b;--bad:#e07878;--shadow:0 22px 56px rgba(0,0,0,.28)}*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:radial-gradient(circle at 78% 0,#1b1810 0,transparent 32%),var(--bg);color:var(--text);font:14px/1.5 Inter,Segoe UI,system-ui,sans-serif}button,input,select{font:inherit}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--text)}.brand img{width:42px;height:42px;object-fit:contain}.brand strong{display:block;font:20px Georgia,serif}.brand small,.muted{color:var(--muted)}.topbar{height:70px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 clamp(18px,4vw,52px);border-bottom:1px solid var(--line);background:rgba(8,11,12,.94);backdrop-filter:blur(18px);position:sticky;top:0;z-index:10}.topnav{display:flex;height:100%}.topnav a{display:grid;place-items:center;padding:0 24px;color:var(--muted);text-decoration:none;border-bottom:2px solid transparent;font-weight:750}.topnav a.active,.topnav a:hover{color:var(--gold2);border-color:var(--gold)}button,.button{min-height:40px;border:1px solid #434845;border-radius:10px;background:#171b1c;color:var(--text);padding:9px 14px;font-weight:750;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}.primary{border-color:#bd8a31;background:linear-gradient(180deg,#c19343,#916521);color:#fff}.button:hover,button:hover{border-color:var(--gold)}.eyebrow{font-size:11px;letter-spacing:.16em;color:var(--gold);font-weight:850;text-transform:uppercase}h1,h2,h3{font-family:Georgia,serif}h1{font-size:clamp(34px,5vw,54px);line-height:1.05;margin:8px 0}.field{width:100%;height:44px;border:1px solid #39403e;border-radius:10px;background:#0c1011;color:var(--text);padding:0 13px;outline:0}.field:focus{border-color:var(--gold)}.panel{border:1px solid var(--line);background:linear-gradient(145deg,rgba(22,28,29,.97),rgba(13,17,18,.98));border-radius:15px;box-shadow:var(--shadow)}.badge{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border:1px solid #48422c;border-radius:999px;font-size:10px;font-weight:850;letter-spacing:.04em;color:var(--gold2);text-transform:uppercase}.badge.good{color:var(--good);border-color:#29513d}.badge.plain{color:var(--muted);border-color:#3b4140}.dot{width:7px;height:7px;border-radius:50%;background:currentColor}@media(max-width:720px){.topbar{height:auto;min-height:64px;padding:10px 14px}.topnav a{padding:0 10px}.brand small{display:none}}
"""


def _page(title: str, body: str, *, script: str = "") -> bytes:
    device_init = r'''<script>(function(){function applyDeviceMode(){var narrow=matchMedia('(max-width:760px)').matches,coarse=matchMedia('(pointer:coarse)').matches,touch=(navigator.maxTouchPoints||0)>0,ua=!!(navigator.userAgentData&&navigator.userAgentData.mobile)||/Android|iPhone|iPod|Mobile/i.test(navigator.userAgent);document.documentElement.dataset.device=(ua||(coarse&&touch&&innerWidth<=1100)||narrow)?'mobile':'desktop';document.documentElement.dataset.input=(coarse||touch)?'touch':'pointer'}applyDeviceMode();addEventListener('resize',applyDeviceMode,{passive:true});addEventListener('orientationchange',applyDeviceMode,{passive:true})})();</script>'''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#090c0d"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><title>{html.escape(title)}</title>{device_init}<style>{SHELL_CSS}</style></head><body>{body}{f'<script>{script}</script>' if script else ''}</body></html>'''.encode("utf-8")


def public_browser_html() -> bytes:
    body = r'''
<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>Server Browser</small></span></a><nav class="topnav"><a class="active" href="/servers">Worlds</a><a href="/api/v1">API</a></nav></header>
<div class="browser"><aside class="filters panel"><div><div class="eyebrow">Discover</div><h3>World filters</h3></div><button class="quick active" data-filter="all">All Worlds <b id="count-all">0</b></button><button class="quick" data-filter="online"><span class="dot"></span> Online <b id="count-online">0</b></button><button class="quick" data-filter="sync">Sync Ready <b id="count-sync">0</b></button><button class="quick" data-filter="vanilla">Vanilla <b id="count-vanilla">0</b></button><button class="quick" data-filter="modded">Modded <b id="count-modded">0</b></button><div class="selects"><label>Region<select class="field" id="region"><option value="">All regions</option></select></label><label>Access<select class="field" id="access"><option value="">Any access</option><option value="open">No password</option><option value="password">Password</option></select></label></div><a class="admin-entry" href="/admin/login"><span class="admin-mark">⚿</span><span><b>Server Admin</b><small>Link and manage a hosted World</small></span><span>→</span></a></aside>
<main><section class="hero"><div class="eyebrow">Public directory · native + sync</div><h1>Find your next World</h1><p>Native Dragonwilds discoveries stay visible. Worlds that answer the Dragonwilds Sync fingerprint probe are promoted with richer metadata and Sync Ready actions.</p></section><section class="toolbar"><input id="search" class="field" placeholder="Search Worlds, descriptions, regions, or tags…"><select id="sort" class="field"><option value="featured">Featured</option><option value="players">Players</option><option value="ping">Lowest ping</option><option value="name">Name</option></select><button id="refresh">↻ Refresh</button></section><div class="directory-note"><b>Layered discovery</b><span>Game-native public sessions + configured manifests + direct fingerprint verification</span><span id="updated">Loading…</span></div><section id="cards" class="cards"></section><nav id="world-pages" class="world-pages" aria-label="World directory pages"></nav><div id="empty" class="panel empty" hidden>No Worlds match these filters.</div></main></div>'''
    script = r'''
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let rows=[],active='all',page=1,pageCount=1,total=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function flag(code){code=String(code||'').toUpperCase();return /^[A-Z]{2}$/.test(code)?String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt())):'🌐'}
function gameTags(w){return [...new Set([...(w.game_tags||(!w.sync_ready?w.tags||[]:[])),w.game_mode,w.content_type].filter(Boolean))].slice(0,6)}
function syncTags(w){return [...new Set([...(w.sync_tags||(w.sync_ready?w.tags||[]:[]))].filter(Boolean))].slice(0,6)}
 function identityBadges(w){const a=String(w.audience||'general'),c=w.community||{};return (a==='kid_friendly'?'<span class="badge good">🛡 Kid-Friendly</span>':a==='adults_only'?'<span class="badge plain">18+ Adults Only</span>':'')+((c.discord_invite||c.discord_guild_id)?'<span class="badge plain">◉ Community</span>':'')+(w.community_rules?'<span class="badge plain">Community Rules</span>':'')}
 function platformBadges(w){const c=w.platform_compatibility||{},defs=[['steam','Steam'],['epic','Epic Games'],['nintendo','Nintendo'],['playstation','PlayStation'],['xbox','Xbox']];return `<div class="platforms">${defs.filter(([key])=>c[key]===true).map(([key,label])=>`<img src="/assets/platforms/${key}.svg" title="${esc(label)} compatible" alt="${esc(label)}">`).join('')}</div>`}
function tagGroups(w){const game=gameTags(w),sync=syncTags(w);return `<div class="tag-groups">${game.length?`<div class="tag-group game"><b>DRAGONWILDS</b>${game.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}${sync.length?`<div class="tag-group sync"><b>SYNC</b>${sync.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}</div>`}
 function card(w){const sync=!!w.sync_ready,online=w.online!==false,players=Number(w.players||0),max=Number(w.max_players||0);return `<article class="world-card panel"><div class="banner"${w.banner_b64?` style="background-image:url('${esc(w.banner_b64)}')"`:''}><span class="source">${esc(w.source_label||'Dragonwilds')}</span></div><div class="world-body"><div class="world-icon">${w.icon_b64?`<img src="${esc(w.icon_b64)}" alt="">`:esc((w.world_name||'W')[0])}</div><div class="world-copy"><div class="title-line"><h2>${esc(w.world_name||'Unnamed World')}</h2>${identityBadges(w)}${sync?'<span class="badge good">◆ Sync Ready</span>':'<span class="badge plain">Vanilla discovery</span>'}</div><p>${esc(w.description||'A discovered RuneScape: Dragonwilds World.')}</p>${platformBadges(w)}${tagGroups(w)}</div><dl><div><dt>Players</dt><dd>${players}${max?' / '+max:''}</dd></div><div><dt>Region</dt><dd>${flag(w.country_code)} ${esc(w.region||w.country_name||'Unknown')}</dd></div><div><dt>Ping</dt><dd>${w.ping_ms!=null?Math.round(w.ping_ms)+' ms':'—'}</dd></div></dl></div><footer><span>${w.password_required?'🔒 Password':'◇ Open'} · ${w.modded?'Modded':'Vanilla'}</span><a class="button ${sync?'primary':''}" href="/servers/${encodeURIComponent(w.id)}">Details</a></footer></article>`}
function render(){page=Math.max(1,Math.min(page,pageCount));$('#cards').innerHTML=rows.map(card).join('');const pager=$('#world-pages');pager.hidden=pageCount<=1;pager.innerHTML=Array.from({length:pageCount},(_,i)=>`<button class="${page===i+1?'active':''}" data-world-page="${i+1}" aria-current="${page===i+1?'page':'false'}">${i+1}</button>`).join('');pager.querySelectorAll('[data-world-page]').forEach(button=>button.onclick=()=>{page=Number(button.dataset.worldPage||1);load().then(()=>document.getElementById('cards')?.scrollIntoView({behavior:'smooth',block:'start'}))});$('#empty').hidden=!!total;}
async function load(){const params=new URLSearchParams({page:String(page),search:$('#search').value.trim(),region:$('#region').value,access:$('#access').value,active,sort:$('#sort').value});const r=await fetch('/api/v1/worlds?'+params,{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Directory unavailable');rows=d.worlds||[];page=Number(d.page||1);pageCount=Number(d.page_count||1);total=Number(d.world_count||0);const counts=d.counts||{};$('#count-all').textContent=counts.all||0;$('#count-online').textContent=counts.online||0;$('#count-sync').textContent=counts.sync||0;$('#count-vanilla').textContent=counts.vanilla||0;$('#count-modded').textContent=counts.modded||0;const current=$('#region').value,rs=d.regions||[];$('#region').innerHTML='<option value="">All regions</option>'+rs.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');$('#updated').textContent='Updated '+new Date(d.generated_at*1000).toLocaleTimeString();render()}
$$('.quick').forEach(b=>b.onclick=()=>{$$('.quick').forEach(x=>x.classList.remove('active'));b.classList.add('active');active=b.dataset.filter;page=1;load()});let searchTimer=0;$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=1;load()},180)});['region','access','sort'].forEach(id=>$('#'+id).addEventListener('change',()=>{page=1;load()}));$('#refresh').onclick=load;load().catch(e=>{$('#updated').textContent=e.message});setInterval(load,30000);
'''
    extra = r'''
<style>.browser{width:min(1540px,calc(100% - 34px));margin:22px auto 70px;display:grid;grid-template-columns:250px minmax(0,1fr);gap:28px}.filters{padding:17px;align-self:start;position:sticky;top:92px;min-height:calc(100vh - 116px);display:flex;flex-direction:column}.filters h3{margin:4px 0 16px;font-size:20px}.quick{width:100%;border:0;border-radius:8px;background:transparent;justify-content:space-between;color:var(--muted);padding:10px}.quick.active{background:#242318;color:var(--gold2)}.quick .dot{background:var(--good)}.selects{display:grid;gap:12px;margin-top:18px;padding-top:18px;border-top:1px solid var(--line2)}label{display:grid;gap:6px;color:var(--muted);font-size:11px;font-weight:750}.admin-entry{margin-top:auto;border:1px solid #4b4329;border-radius:12px;background:linear-gradient(145deg,#262216,#151714);color:var(--text);text-decoration:none;padding:12px;display:grid;grid-template-columns:34px 1fr auto;align-items:center;gap:9px}.admin-entry small{display:block;color:var(--muted);font-size:10px}.admin-mark{width:32px;height:32px;border-radius:8px;display:grid;place-items:center;background:#b98731;color:#fff;font-size:19px}.hero{padding:30px 2px 18px}.hero p{max-width:800px;color:var(--muted);font-size:15px}.toolbar{display:grid;grid-template-columns:minmax(240px,1fr) 180px auto;gap:10px}.directory-note{display:flex;gap:14px;align-items:center;margin:14px 0;padding:11px 14px;border:1px solid var(--line2);border-radius:10px;color:var(--muted);font-size:11px}.directory-note b{color:var(--gold2)}.directory-note #updated{margin-left:auto}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.world-card{overflow:hidden}.banner{height:94px;background:linear-gradient(120deg,#322b18,#132023 48%,#0c1112);background-size:cover;background-position:center;position:relative}.source{position:absolute;right:10px;top:10px;padding:4px 7px;border-radius:7px;background:#090d0ddd;color:var(--muted);font-size:9px;text-transform:uppercase}.world-body{display:grid;grid-template-columns:58px minmax(0,1fr) 118px;gap:13px;padding:14px}.world-icon{width:58px;height:58px;border:1px solid #665330;border-radius:12px;background:#0a0d0e;display:grid;place-items:center;color:var(--gold2);font:28px Georgia,serif;overflow:hidden}.world-icon img{width:100%;height:100%;object-fit:cover}.title-line{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.title-line h2{font-size:21px;margin:0}.world-copy p{color:var(--muted);margin:4px 0 9px;font-size:12px}.tagline{display:flex;gap:5px;flex-wrap:wrap}.tagline span{border:1px solid #373d3b;border-radius:6px;padding:3px 6px;font-size:9px;color:var(--muted)}dl{margin:0;border-left:1px solid var(--line2);padding-left:12px}dl div{display:flex;justify-content:space-between;gap:8px;font-size:10px;margin-bottom:6px}dt{color:var(--muted)}dd{margin:0}footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;border-top:1px solid var(--line2);color:var(--muted);font-size:10px}.empty{padding:34px;text-align:center;color:var(--muted)}@media(max-width:1100px){.cards{grid-template-columns:1fr}.browser{grid-template-columns:220px minmax(0,1fr)}}@media(max-width:760px){.browser{display:block;width:min(100% - 20px,1540px)}.filters{position:static;min-height:0;margin-bottom:12px}.admin-entry{margin-top:20px}.toolbar{grid-template-columns:1fr}.directory-note{align-items:flex-start;flex-direction:column}.directory-note #updated{margin:0}.world-body{grid-template-columns:48px 1fr}.world-icon{width:48px;height:48px}dl{grid-column:1/-1;border:0;padding:10px 0 0;display:flex;gap:15px}.topnav{display:none}}</style>'''
    return _page("Dragonwilds Sync · Worlds", extra + body, script=script)


def admin_login_html() -> bytes:
    body = r'''<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>Remote</small></span></a><a class="button" href="/servers">← Back to Worlds</a></header><main class="login-wrap"><section class="login-intro"><img src="/assets/icon.png" alt=""><div class="eyebrow">Remote server management</div><h1>Link your hosted World</h1><p>Sign in with a desktop-created server user. The World owner may leave Account blank and use the Server Admin Password for recovery access.</p><ul><li>Persistent per-user permissions</li><li>Every login, request, and action is audited</li><li>No operating-system shell or unrestricted file access</li></ul></section><section class="panel login-panel"><div class="eyebrow">Server Admin</div><h2>Sign in to a World</h2><p class="muted">The local Dragonwilds Sync installation remains authoritative.</p><form id="login"><label>World Name<input class="field" id="world" autocomplete="organization" required></label><label>Server user (blank for owner)<input class="field" id="account" autocomplete="username" placeholder="Desktop-created account"></label><label>Password<input class="field" id="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">Link &amp; open Server Admin →</button><div id="message"></div></form><div class="login-note">Server users and their category permissions are created locally in WebHost → Settings &amp; Authority. The owner fallback uses the World’s Server Admin Password.</div></section></main><style>.login-wrap{width:min(1060px,calc(100% - 28px));min-height:calc(100vh - 70px);margin:auto;display:grid;grid-template-columns:1fr minmax(360px,470px);gap:42px;align-items:center}.login-intro{text-align:center;padding:40px}.login-intro>img{width:160px;height:160px;object-fit:contain;filter:drop-shadow(0 18px 35px #000)}.login-intro p{color:var(--muted);font-size:15px}.login-intro ul{display:inline-grid;gap:8px;text-align:left;color:var(--muted);padding-left:20px}.login-panel{padding:28px}.login-panel h2{font-size:28px;margin:5px 0}.login-panel form{display:grid;gap:15px;margin-top:22px}.login-panel button{width:100%;margin-top:4px}.login-note{margin-top:18px;padding:12px;border:1px solid var(--line);border-radius:10px;color:var(--muted);font-size:11px}#message{min-height:20px;color:var(--bad);font-size:12px}@media(max-width:800px){.login-wrap{grid-template-columns:1fr}.login-intro{padding:36px 16px 0}.login-intro>img{width:110px;height:110px}}</style>'''
    script = r'''document.getElementById('login').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('message');m.textContent='Linking…';const r=await fetch('/api/v1/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({world_name:document.getElementById('world').value,username:document.getElementById('account').value,password:document.getElementById('password').value})});const d=await r.json();if(!r.ok){m.textContent=d.error||'World login failed';return}location.href='/admin/server'}'''
    return _page("Dragonwilds Sync · Server Admin", body, script=script)


def remote_admin_html() -> bytes:
    body = r'''<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>Remote</small></span></a><nav class="topnav"><a class="active" href="/admin/server">My Server</a><a href="/servers">Worlds</a></nav><button id="logout">Sign out</button></header><main class="admin-wrap"><section class="admin-head"><div><div class="eyebrow">Linked World · audited session</div><h1 id="world-name">Server Admin</h1><p id="description" class="muted"></p></div><span id="online" class="badge plain">Loading</span></section><section id="stats" class="stats"></section><div class="admin-grid"><section class="panel workspace"><nav class="tabs"><button class="active" data-tab="overview">Overview</button><button data-tab="mods">Mods</button><button data-tab="config">Config</button><button data-tab="audit">Audit</button></nav><div id="tab-body"></div></section><aside class="panel actions"><h2>Server actions</h2><p class="muted">Commands are structured, World-scoped, and executed by the local application.</p><button class="start" data-action="start">▶ Start World</button><button class="stop" data-action="stop">■ Stop World</button><button data-action="restart">↻ Soft Restart</button><button data-action="refresh">◇ Refresh Metadata</button><div id="action-message"></div><hr><h3>Session</h3><div id="session"></div></aside></div></main><style>.admin-wrap{width:min(1320px,calc(100% - 32px));margin:30px auto 70px}.admin-head{display:flex;align-items:end;justify-content:space-between;gap:20px}.admin-head h1{margin-bottom:4px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0}.stat{padding:15px}.stat span{color:var(--muted);font-size:10px;text-transform:uppercase}.stat b{display:block;font-size:22px;margin-top:5px}.admin-grid{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:15px}.workspace{min-height:470px;overflow:hidden}.tabs{display:flex;border-bottom:1px solid var(--line)}.tabs button{border:0;border-radius:0;background:transparent;color:var(--muted);padding:14px 18px}.tabs button.active{color:var(--gold2);box-shadow:inset 0 -2px var(--gold)}#tab-body{padding:20px}.overview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.info{padding:15px;border:1px solid var(--line2);border-radius:11px}.info h3{margin:0 0 8px}.kv{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid #262c2b;color:var(--muted)}.kv b{color:var(--text);text-align:right}.actions{padding:18px;align-self:start;display:grid;gap:9px}.actions h2{margin:0}.actions button{width:100%}.actions .start{border-color:#2f6d4b;color:var(--good)}.actions .stop{border-color:#713939;color:#f18a8a}.actions hr{border:0;border-top:1px solid var(--line);width:100%}.actions h3{margin:4px 0}.audit-row{display:grid;grid-template-columns:160px 1fr auto;gap:10px;padding:10px 0;border-bottom:1px solid var(--line2);font-size:12px}.audit-row small{color:var(--muted)}#action-message{min-height:18px;color:var(--muted);font-size:11px}@media(max-width:900px){.stats{grid-template-columns:1fr 1fr}.admin-grid{grid-template-columns:1fr}.overview-grid{grid-template-columns:1fr}}@media(max-width:560px){.stats{grid-template-columns:1fr}.tabs{overflow:auto}.admin-head{align-items:start;flex-direction:column}}</style>'''
    script = r'''let csrf='',data=null,tab='overview';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function kv(k,v){return `<div class="kv"><span>${esc(k)}</span><b>${esc(v??'—')}</b></div>`}function renderTab(){const p=data.profile||{},r=data.runtime||{},a=data.audit||[];if(tab==='overview')$('#tab-body').innerHTML=`<div class="overview-grid"><div class="info"><h3>World identity</h3>${kv('World Name',p.world_name)}${kv('Classification',p.content_type)}${kv('Game mode',p.game_mode)}${kv('Manifest revision',p.manifest_version)}${kv('Fingerprint',p.fingerprint||'Pending broadcast')}</div><div class="info"><h3>Connection</h3>${kv('Internal route',p.internal_route)}${kv('External route',p.external_route)}${kv('Game port',p.game_port)}${kv('Sync port',p.sync_port)}${kv('Server process',r.running?'Running':'Stopped')}</div></div>`;else if(tab==='mods')$('#tab-body').innerHTML=`<div class="info"><h3>Profile & mods</h3>${kv('Declared type',p.modded?'Modded':'Vanilla')}${kv('Tags',(p.tags||[]).join(', ')||'None')}${kv('UE4SS',p.auto_ue4ss?'Managed':'Manual')}${kv('RuneSchema',p.auto_runeschema?'Managed':'Manual')}</div>`;else if(tab==='config')$('#tab-body').innerHTML=`<div class="info"><h3>Safe configuration summary</h3>${kv('World password',p.password_required?'Configured':'Not configured')}${kv('Admin password','Configured and never exposed')}${kv('Public listing',p.visibility)}${kv('Remote authority','Local Dragonwilds Sync agent')}</div>`;else $('#tab-body').innerHTML=a.length?a.map(x=>`<div class="audit-row"><small>${new Date(x.at*1000).toLocaleString()}</small><span><b>${esc(x.action)}</b><br><small>${esc(x.detail||'')}</small></span><small>${esc(x.remote_ip||'local')}</small></div>`).join(''):'<p class="muted">No remote activity yet.</p>'}async function load(){const r=await fetch('/api/v1/admin/session',{cache:'no-store'});if(r.status===401){location.href='/admin/login';return}data=await r.json();csrf=data.csrf;const p=data.profile||{},rt=data.runtime||{};$('#world-name').textContent=p.world_name||'Server Admin';$('#description').textContent=p.description||'Dragonwilds Sync hosted World';$('#online').textContent=rt.running?'● Online':'○ Offline';$('#online').className='badge '+(rt.running?'good':'plain');$('#stats').innerHTML=[['Players',rt.players_online||0],['Uptime',rt.uptime_text||'—'],['CPU',rt.cpu_percent!=null?rt.cpu_percent+'%':'—'],['RAM',rt.ram_text||'—'],['Sync',rt.sync_status||'Ready']].map(x=>`<div class="stat panel"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$('#session').innerHTML=kv('Role',data.session.role)+kv('Expires',new Date(data.session.expires_at*1000).toLocaleTimeString());renderTab()}document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');tab=b.dataset.tab;renderTab()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const m=$('#action-message');m.textContent='Sending command…';const r=await fetch('/api/v1/admin/action',{method:'POST',headers:{'Content-Type':'application/json','X-DWS-CSRF':csrf},body:JSON.stringify({action:b.dataset.action})}),d=await r.json();m.textContent=r.ok?'Command completed.':(d.error||'Command failed');await load()});$('#logout').onclick=async()=>{await fetch('/api/v1/admin/logout',{method:'POST',headers:{'X-DWS-CSRF':csrf}});location.href='/servers'};load();setInterval(load,10000);'''
    return _page("Dragonwilds Sync · Remote", body, script=script)


def api_index_html(openapi: dict) -> bytes:
    rows = "".join(f'<div class="route"><code>{html.escape(method.upper())}</code><b>{html.escape(path)}</b><span>{html.escape((spec or {}).get("summary", ""))}</span></div>' for path, methods in openapi.get("paths", {}).items() for method, spec in methods.items())
    body = f'''<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>Directory API</small></span></a><a class="button" href="/servers">← Server Browser</a></header><main class="api"><div class="eyebrow">Versioned · public-safe · read-only discovery</div><h1>Build your own World browser</h1><p class="muted">Any website may consume the public v1 endpoints. Administrative endpoints are deliberately same-origin and require a linked, audited Server Admin session.</p><div class="panel routes">{rows}</div><p><a class="button primary" href="/api/v1/openapi.json">OpenAPI JSON</a> <a class="button" href="/api/v1/worlds">Live Worlds JSON</a></p></main><style>.api{{width:min(920px,calc(100% - 28px));margin:50px auto}}.routes{{padding:12px;margin:24px 0}}.route{{display:grid;grid-template-columns:60px 260px 1fr;gap:12px;padding:12px;border-bottom:1px solid var(--line2)}}.route code{{color:var(--gold2)}}.route span{{color:var(--muted)}}@media(max-width:660px){{.route{{grid-template-columns:55px 1fr}}.route span{{grid-column:1/-1}}}}</style>'''
    return _page("Dragonwilds Sync · API", body)


def detail_html(world_id: str) -> bytes:
    safe = json.dumps(str(world_id))
    body = '''<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>World details</small></span></a><a class="button" href="/servers">← All Worlds</a></header><main id="detail" class="detail"><div class="panel loading">Loading World…</div></main><style>.detail{width:min(980px,calc(100% - 28px));margin:44px auto}.detail-card{overflow:hidden}.detail-banner{height:220px;background:linear-gradient(130deg,#332816,#122123);background-size:cover;background-position:center}.detail-body{padding:25px}.detail-heading{display:grid;grid-template-columns:76px minmax(0,1fr);gap:16px;align-items:center}.detail-icon{width:76px;height:76px;border-radius:14px;object-fit:cover;background:#0a0d0e}.detail-body h1{font-size:42px;margin:0}.detail-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.meta div{padding:12px;border:1px solid var(--line2);border-radius:10px}.meta small{display:block;color:var(--muted)}.world-rules,.all-world-metadata{margin:20px 0;padding:16px;border:1px solid var(--line2);border-radius:12px;background:#0b1110}.world-rules h2{font-size:18px;margin:0 0 8px}.world-rules p{white-space:pre-wrap;color:var(--muted);margin:0}.all-world-metadata summary{cursor:pointer;font-weight:800;color:var(--gold2)}.all-world-metadata pre{max-height:420px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font:11px/1.5 Consolas,monospace}.loading{padding:40px;text-align:center}</style>'''
    script = f'''const id={safe};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));fetch('/api/v1/worlds/'+encodeURIComponent(id)).then(r=>r.json().then(d=>[r,d])).then(([r,d])=>{{if(!r.ok)throw Error(d.error||'World unavailable');const w=d.world;document.getElementById('detail').innerHTML=`<article class="detail-card panel"><div class="detail-banner"${{w.banner_b64?` style="background-image:url('${{esc(w.banner_b64)}}')"`:''}}></div><div class="detail-body"><div class="detail-heading">${{w.icon_b64?`<img class="detail-icon" src="${{esc(w.icon_b64)}}" alt="">`:'<span class="detail-icon"></span>'}}<div><div class="eyebrow">${{w.sync_ready?'Dragonwilds Sync Ready':'Native Dragonwilds discovery'}}</div><h1>${{esc(w.world_name)}}</h1></div></div><p class="muted">${{esc(w.description||'A discovered RuneScape: Dragonwilds World.')}}</p><div class="meta"><div><small>Players</small><b>${{w.players||0}} / ${{w.max_players||'—'}}</b></div><div><small>Region</small><b>${{esc(w.region||w.country_name||'Unknown')}}</b></div><div><small>Ping</small><b>${{w.ping_ms!=null?Math.round(w.ping_ms)+' ms':'—'}}</b></div><div><small>Mode</small><b>${{esc(w.game_mode||w.content_type||(w.modded?'Modded':'Vanilla'))}}</b></div><div><small>Access</small><b>${{w.password_required?'Password':'Open'}}</b></div><div><small>Platforms</small><b>${{esc(Object.entries(w.platform_compatibility||{{}}).filter(([,enabled])=>enabled).map(([name])=>name).join(', ')||'Unspecified')}}</b></div><div><small>Tags</small><b>${{esc((w.tags||[]).join(', ')||'None')}}</b></div><div><small>Provider</small><b>${{esc(w.source_label||w.source||'Dragonwilds')}}</b></div></div>${{w.community_rules?`<section class="world-rules"><h2>Community Rules</h2><p>${{esc(w.community_rules)}}</p></section>`:''}}<details class="all-world-metadata"><summary>All World metadata</summary><pre>${{esc(JSON.stringify(w,null,2))}}</pre></details><div class="detail-actions">${{w.sync_ready?'<button class="primary" disabled>Sync & Play · desktop handoff ready</button>':'<button disabled>View-only native World</button>'}}<a class="button" href="/api/v1/worlds/${{encodeURIComponent(w.id)}}">Metadata JSON</a></div></div></article>`}}).catch(e=>document.getElementById('detail').innerHTML='<div class="panel loading">'+esc(e.message)+'</div>')'''
    return _page("Dragonwilds Sync · World", body, script=script)


# The permission-aware portal intentionally mirrors the desktop server workspace.
# It is defined last so older source bundles can still import this module while
# receiving the hardened WebHost surface.
def remote_admin_html() -> bytes:
    body = r'''<header class="topbar"><a class="brand" href="/servers"><img src="/assets/icon.png" alt=""><span><strong>Dragonwilds Sync</strong><small>WebHost</small></span></a><nav class="topnav"><a class="active" href="/admin/server">My Server</a><a href="/servers">Worlds</a></nav><button id="logout">Sign out</button></header>
<main class="admin-wrap"><section class="admin-head"><div><div class="eyebrow">Linked World · desktop-authorized session</div><h1 id="world-name">Server Admin</h1><p id="description" class="muted"></p></div><span id="online" class="badge plain">Loading</span></section><section id="stats" class="stats"></section><div class="admin-grid"><section class="panel workspace"><nav class="tabs"><button class="active" data-tab="overview">Overview</button><button data-tab="mods">Mods</button><button data-tab="config">Config &amp; Files</button><button data-tab="audit">Audit</button></nav><div id="tab-body"></div></section><aside class="panel actions"><h2>Server actions</h2><p class="muted">Each command is World-scoped, audited, and allowed only when granted in the desktop WebHost workspace.</p><button class="start" data-action="start">▶ Start World</button><button class="stop" data-action="stop">■ Stop World</button><button data-action="restart">↻ Soft Restart</button><button data-action="refresh">◇ Refresh Metadata</button><div id="action-message"></div><hr><h3>Session authority</h3><div id="session"></div></aside></div></main>
<style>.admin-wrap{width:min(1320px,calc(100% - 32px));margin:30px auto 70px}.admin-head{display:flex;align-items:end;justify-content:space-between;gap:20px}.admin-head h1{margin-bottom:4px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0}.stat{padding:15px}.stat span{color:var(--muted);font-size:10px;text-transform:uppercase}.stat b{display:block;font-size:22px;margin-top:5px}.admin-grid{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:15px}.workspace{min-height:500px;overflow:hidden}.tabs{display:flex;border-bottom:1px solid var(--line)}.tabs button{border:0;border-radius:0;background:transparent;color:var(--muted);padding:14px 18px}.tabs button.active{color:var(--gold2);box-shadow:inset 0 -2px var(--gold)}.tabs button[hidden]{display:none}#tab-body{padding:20px}.overview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.info,.unit,.file-row{padding:15px;border:1px solid var(--line2);border-radius:11px}.info h3,.unit h3{margin:0 0 8px}.kv{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid #262c2b;color:var(--muted)}.kv b{color:var(--text);text-align:right}.actions{padding:18px;align-self:start;display:grid;gap:9px}.actions h2{margin:0}.actions button{width:100%}.actions .start{border-color:#2f6d4b;color:var(--good)}.actions .stop{border-color:#713939;color:#f18a8a}.actions hr{border:0;border-top:1px solid var(--line);width:100%}.actions h3{margin:4px 0}.actions button:disabled,.tabs button:disabled{opacity:.38;cursor:not-allowed}.audit-row{display:grid;grid-template-columns:160px 1fr auto;gap:10px;padding:10px 0;border-bottom:1px solid var(--line2);font-size:12px}.audit-row small{color:var(--muted)}.units,.files{display:grid;gap:10px}.unit-head,.file-row{display:flex;justify-content:space-between;gap:12px;align-items:center}.unit p{margin:5px 0;color:var(--muted);font-size:11px}.editor{display:grid;gap:10px}.editor textarea{min-height:290px;resize:vertical;background:#090d0e;color:var(--text);border:1px solid var(--line2);border-radius:10px;padding:12px;font:12px/1.5 Consolas,monospace}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.grant{color:var(--good);font-size:10px}.denied{color:var(--bad);font-size:10px}#action-message{min-height:18px;color:var(--muted);font-size:11px}@media(max-width:900px){.stats{grid-template-columns:1fr 1fr}.admin-grid{grid-template-columns:1fr}.overview-grid{grid-template-columns:1fr}}@media(max-width:560px){.stats{grid-template-columns:1fr}.tabs{overflow:auto}.admin-head{align-items:start;flex-direction:column}.unit-head,.file-row{align-items:start;flex-direction:column}}</style>'''
    script = r'''let csrf='',data=null,tab='overview',openedFile='';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function kv(k,v){return `<div class="kv"><span>${esc(k)}</span><b>${esc(v??'—')}</b></div>`}function allowed(k){return !!(data.permissions||{})[k]}async function command(action,payload={}){const r=await fetch('/api/v1/admin/action',{method:'POST',headers:{'Content-Type':'application/json','X-DWS-CSRF':csrf},body:JSON.stringify({action,payload})}),d=await r.json();if(!r.ok)throw Error(d.error||'Command failed');return d.result||{}}function renderTab(){const p=data.profile||{},r=data.runtime||{},a=data.audit||[],mods=data.mods||[],configs=data.configs||[];if(tab==='overview'){$('#tab-body').innerHTML=`<div class="overview-grid"><div class="info"><h3>World identity</h3>${kv('World Name',p.world_name)}${kv('Classification',p.content_type)}${kv('Game mode',p.game_mode)}${kv('Manifest revision',p.manifest_version)}${kv('Fingerprint',p.fingerprint||'Pending broadcast')}</div><div class="info"><h3>Connection</h3>${kv('Internal route',p.internal_route)}${kv('External route',p.external_route)}${kv('Game port',p.game_port)}${kv('Sync port',p.sync_port)}${kv('Server process',r.running?'Running':'Stopped')}</div></div>`;return}if(tab==='mods'){if(!allowed('view_mods')){$('#tab-body').innerHTML='<p class="denied">The desktop application has not granted mod visibility.</p>';return}$('#tab-body').innerHTML=`<div class="toolbar"><strong>Live mod inventory</strong><span class="${allowed('write_mods')?'grant':'denied'}">${allowed('write_mods')?'Metadata and hotload writing granted':'Read-only authority'}</span></div><div class="units">${mods.length?mods.map(m=>`<article class="unit"><div class="unit-head"><div><h3>${esc(m.name||m.key)}</h3><p>${esc(m.group||'mod')} · ${esc(m.classification||'server_only')} · ${(m.tags||[]).map(esc).join(', ')||'no tags'}</p></div>${allowed('write_mods')?`<button data-edit-mod="${esc(m.key)}">Edit tags / hotload</button>`:''}</div></article>`).join(''):'<p class="muted">No managed mod units were found.</p>'}</div>`;$$('[data-edit-mod]').forEach(b=>b.onclick=async()=>{const m=mods.find(x=>x.key===b.dataset.editMod);const tags=prompt('Comma-separated tags',(m.tags||[]).join(', '));if(tags===null)return;try{await command('mod_update',{key:m.key,tags:tags.split(',').map(x=>x.trim()).filter(Boolean),hotload_capable:!!m.hotload_capable});await load()}catch(e){alert(e.message)}});return}if(tab==='config'){if(!allowed('view_config')){$('#tab-body').innerHTML='<p class="denied">The desktop application has not granted configuration visibility.</p>';return}if(openedFile){return}$('#tab-body').innerHTML=`<div class="toolbar"><strong>Managed configuration files</strong><span class="${allowed('write_config')?'grant':'denied'}">${allowed('write_config')?'Live writes granted':'Read-only authority'}</span></div><div class="files">${configs.length?configs.map(f=>`<div class="file-row"><div><b>${esc(f.relative_path||f.name||'Config')}</b><div class="muted">${esc(f.kind||'managed')} ${f.hotload_capable?'· hotload capable':''}</div></div><button data-open-config="${esc(f.relative_path||'')}">Open</button></div>`).join(''):'<p class="muted">No managed configuration files were found.</p>'}</div>`;$$('[data-open-config]').forEach(b=>b.onclick=()=>openConfig(b.dataset.openConfig));return}$('#tab-body').innerHTML=allowed('view_audit')?(a.length?a.map(x=>`<div class="audit-row"><small>${new Date(x.at*1000).toLocaleString()}</small><span><b>${esc(x.action)}</b><br><small>${esc(x.detail||'')}</small></span><small>${esc(x.remote_ip||'local')}</small></div>`).join(''):'<p class="muted">No remote activity yet.</p>'):'<p class="denied">The desktop application has not granted audit visibility.</p>'}async function openConfig(path){try{const f=await command('config_open',{relative_path:path});openedFile=path;$('#tab-body').innerHTML=`<div class="editor"><div class="toolbar"><button id="back-files">← Files</button><strong>${esc(path)}</strong><span class="${allowed('write_config')?'grant':'denied'}">${f.hotload_capable?'Hotload capable':'Restart may be required'}</span></div><textarea id="config-content" ${allowed('write_config')?'':'readonly'}>${esc(f.content||'')}</textarea>${allowed('write_config')?'<button class="primary" id="save-config">Save through desktop authority</button>':''}</div>`;$('#back-files').onclick=()=>{openedFile='';renderTab()};if(allowed('write_config'))$('#save-config').onclick=async()=>{try{await command('config_save',{relative_path:path,content:$('#config-content').value});await load();alert('Configuration saved and audited.')}catch(e){alert(e.message)}}}catch(e){alert(e.message)}}async function load(){const r=await fetch('/api/v1/admin/session',{cache:'no-store'});if(r.status===401){location.href='/admin/login';return}data=await r.json();csrf=data.csrf;const p=data.profile||{},rt=data.runtime||{};$('#world-name').textContent=p.world_name||'Server Admin';$('#description').textContent=p.description||'Dragonwilds Sync hosted World';$('#online').textContent=rt.running?'● Online':'○ Offline';$('#online').className='badge '+(rt.running?'good':'plain');$('#stats').innerHTML=[['Players',rt.players_online||0],['Uptime',rt.uptime_text||'—'],['CPU',rt.cpu_percent!=null?rt.cpu_percent+'%':'—'],['RAM',rt.ram_text||'—'],['Sync',rt.sync_status||'Ready']].map(x=>`<div class="stat panel"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$('#session').innerHTML=kv('Role',data.session.role)+kv('Expires',new Date(data.session.expires_at*1000).toLocaleTimeString())+kv('Granted',Object.values(data.permissions||{}).filter(Boolean).length+' permissions');$$('[data-action]').forEach(b=>b.disabled=!allowed(b.dataset.action));$$('[data-tab="mods"]')[0].hidden=!allowed('view_mods');$$('[data-tab="config"]')[0].hidden=!allowed('view_config');$$('[data-tab="audit"]')[0].hidden=!allowed('view_audit');if(tab==='mods'&&!allowed('view_mods')||tab==='config'&&!allowed('view_config')||tab==='audit'&&!allowed('view_audit'))tab='overview';renderTab()}$$('.tabs button').forEach(b=>b.onclick=()=>{$$('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');tab=b.dataset.tab;openedFile='';renderTab()});$$('[data-action]').forEach(b=>b.onclick=async()=>{const m=$('#action-message');m.textContent='Sending command…';try{await command(b.dataset.action);m.textContent='Command completed.';await load()}catch(e){m.textContent=e.message}});$('#logout').onclick=async()=>{await fetch('/api/v1/admin/logout',{method:'POST',headers:{'X-DWS-CSRF':csrf}});location.href='/servers'};load();setInterval(()=>{if(!openedFile)load()},10000);'''
    return _page("Dragonwilds Sync · WebHost", body, script=script)


